import { createEventBus } from "@zudojs/events";

const bus = createEventBus();
bus.on("task.completed", (event) => console.log(`email to ${event.payload.userId}: "${event.payload.title}"`));
const tasks = new Map([[1, { id: 1, userId: "ada", title: "Buy milk", done: false }]]);

async function complete(userId, id) {
  const task = tasks.get(id);
  if (!task || task.userId !== userId) throw new Error(`Task ${id} not found`);
  task.done = true;
  await bus.publishEvent({ type: "task.completed", payload: { taskId: id, userId, title: task.title } });
  return task;
}

try {
  await complete("linus", 1);
} catch (error) {
  console.log("linus:", error.message);
}
await complete("ada", 1);
console.log("done:", tasks.get(1).done);

